scenes.motion:
const lembahKanan = el('lembahKanan');
const lembahKiri = el('lembahKiri');
const rekahanMagmaDasar = el('rekahanMagmaDasar');
const matahariRedup = el('matahariRedup');
const uapPanas = el('uapPanas');
const partikelDebu = el('partikelDebu');
const pakisPurbaDepan = el('pakisPurbaDepan');
const pelepahTinggi = el('pelepahTinggi');
const pelepahTengah = el('pelepahTengah');
const pelepahRendah = el('pelepahRendah');

const splitP = mulus(Math.min(1, Math.max(0, (t - 0.8) / 3.4)));
const guncangFaktor = Math.sin(splitP * Math.PI);
const guncangan = getar * guncangFaktor * 5.5;
const mikro = (t > 4.2) ? Math.sin(t * 18) * 0.35 : 0;

if (lembahKanan) {
  const geserX = splitP * 150 + guncangan + mikro;
  lembahKanan.setAttribute('transform', `translate(${geserX.toFixed(2)}, ${(guncangan * 0.25).toFixed(2)})`);
}

if (lembahKiri) {
  lembahKiri.setAttribute('transform', `translate(${(-guncangan * 0.4).toFixed(2)}, ${(guncangan * 0.15).toFixed(2)})`);
}

if (rekahanMagmaDasar) {
  const pendar = 0.55 + splitP * 0.35 + denyut * 0.08 + napas * 0.04;
  rekahanMagmaDasar.setAttribute('opacity', Math.min(1, pendar).toFixed(2));
}

if (matahariRedup) {
  matahariRedup.setAttribute('opacity', (0.28 - splitP * 0.08).toFixed(2));
}

if (uapPanas) {
  const faseUap = (t * 0.32) % 1;
  const uapY = -faseUap * 80;
  const uapAlfa = Math.sin(faseUap * Math.PI) * (0.25 + splitP * 0.55);
  uapPanas.setAttribute('transform', `translate(${(ombak * 4).toFixed(2)}, ${uapY.toFixed(2)})`);
  uapPanas.setAttribute('opacity', uapAlfa.toFixed(2));
}

if (partikelDebu) {
  const debuSiklus = (t * 1.6) % 1;
  const debuY = -debuSiklus * 110;
  const debuAlfa = guncangFaktor * (1 - debuSiklus) * 0.85;
  partikelDebu.setAttribute('transform', `translate(${(Math.sin(t * 12) * 8).toFixed(2)}, ${debuY.toFixed(2)})`);
  partikelDebu.setAttribute('opacity', Math.max(0, debuAlfa).toFixed(2));
}

if (pakisPurbaDepan) {
  pakisPurbaDepan.setAttribute('transform', `translate(${(guncangan * 0.25).toFixed(2)}, ${(guncangan * 0.1).toFixed(2)})`);
}

if (pelepahTinggi) fisika.putar(pelepahTinggi, ombak * 3.5 + guncangan * 0.6, 180, 920);
if (pelepahTengah) fisika.putar(pelepahTengah, ombakC * 2.8 + guncangan * 0.4, 160, 960);
if (pelepahRendah) fisika.putar(pelepahRendah, napas * 2.0 + guncangan * 0.3, 140, 1000);

// skipped: multi-particle array pool; add when individual ember trajectories are required.
// skipped: SVG path morphing for terrain tear; add when mesh rig is provided.

const blast = mulus(Math.min(1, t / 1.8));
const rumble = (t < 2.5 ? getar * (1 - t / 2.5) * 3 : Math.sin(t * 18) * 0.8);

const root = el('kalderaTobaMeledak');
if (root) {
  const gempa = t < 2.0 ? getar * (1 - t / 2.0) * 5 : 0;
  root.setAttribute('transform', `translate(0, ${gempa.toFixed(1)})`);
}

const latar = el('latarBelakang');
if (latar) {
  const tertelan = mulus(Math.min(1, Math.max(0, (t - 0.6) / 3.4)));
  latar.setAttribute('opacity', (1 - tertelan * 0.75).toFixed(2));
}

const kejut = el('gelombangKejut');
if (kejut) {
  const pKejut = Math.min(1, t / 1.4);
  const s = 0.2 + mulus(pKejut) * 3.2;
  kejut.style.transformBox = 'fill-box';
  kejut.style.transformOrigin = 'center';
  kejut.setAttribute('transform', `scale(${s.toFixed(3)})`);
  kejut.setAttribute('opacity', Math.max(0, 1 - pKejut * 1.15).toFixed(2));
}

const bibir = el('strukturBibirKaldera');
if (bibir) {
  bibir.setAttribute('transform', `translate(0, ${rumble.toFixed(1)})`);
}

const magma = el('kawahMagma');
if (magma) {
  magma.setAttribute('opacity', (0.7 + denyut * 0.3).toFixed(2));
}

const kolom = el('kolomAbuStratosfer');
if (kolom) {
  const yAbu = (1 - blast) * 900;
  kolom.setAttribute('transform', `translate(${rumble.toFixed(1)}, ${yAbu.toFixed(1)})`);
}

const batang = el('batangPlinian');
if (batang) {
  batang.setAttribute('opacity', mulus(Math.min(1, t / 0.6)).toFixed(2));
}

const payung = el('payungAbuStratosfer');
if (payung) {
  const pPayung = mulus(Math.min(1, Math.max(0, (t - 0.5) / 3.2)));
  const skala = 0.15 + pPayung * 0.85;
  payung.style.transformBox = 'fill-box';
  payung.style.transformOrigin = 'top center';
  payung.setAttribute('transform', `scale(${skala.toFixed(3)}) translate(${rumble.toFixed(1)}, 0)`);
  payung.setAttribute('opacity', Math.min(1, pPayung * 1.6).toFixed(2));
}

const kilat = el('kilatVulkanik');
if (kilat) {
  const aktif = t > 0.8 && t < 7.2;
  const kedip = aktif && (Math.sin(t * 53) * Math.cos(t * 29) > 0.28);
  kilat.setAttribute('opacity', kedip ? '1' : '0');
}

const bom = el('bomVulkanik');
if (bom) {
  const pBom = Math.min(1, t / 3.0);
  const arcY = -Math.sin(pBom * Math.PI) * 260 + (pBom * 140);
  const arcX = pBom * 80;
  bom.setAttribute('transform', `translate(${arcX.toFixed(1)}, ${arcY.toFixed(1)})`);
  bom.setAttribute('opacity', (t < 0.1 ? 0 : Math.max(0, 1 - Math.max(0, t - 2.2) / 1.2)).toFixed(2));
}

const hujan = el('hujanAbuPartikel');
if (hujan) {
  const pHujan = mulus(Math.min(1, Math.max(0, (t - 1.8) / 4.5)));
  hujan.setAttribute('transform', `translate(${(ombak * 8).toFixed(1)}, ${(pHujan * 220).toFixed(1)})`);
  hujan.setAttribute('opacity', (pHujan * 0.85).toFixed(2));
}

const tebing = el('lapisDepanTebingBatu');
if (tebing) {
  const tremTebing = t < 2.0 ? getar * (1 - t / 2.0) * 1.5 : 0;
  tebing.setAttribute('transform', `translate(0, ${tremTebing.toFixed(1)})`);
}

const pKiri = el('pohonKiriDepan');
if (pKiri) {
  const sentak = (t > 0.2 && t < 2.0) ? Math.sin((t - 0.2) * 4) * 8 * Math.exp(-(t - 0.2) * 1.4) : 0;
  pKiri.style.transformBox = 'fill-box';
  pKiri.style.transformOrigin = 'bottom center';
  pKiri.setAttribute('transform', `rotate(${(-sentak + ombak * 1.6).toFixed(2)})`);
}

const pKanan = el('pohonSiluetDepan');
if (pKanan) {
  const sentak = (t > 0.3 && t < 2.2) ? Math.sin((t - 0.3) * 4) * 7 * Math.exp(-(t - 0.3) * 1.4) : 0;
  pKanan.style.transformBox = 'fill-box';
  pKanan.style.transformOrigin = 'bottom center';
  pKanan.setAttribute('transform', `rotate(${(sentak + ombakC * 1.4).toFixed(2)})`);
}

const cam = el('kameraGuaToba');
if (cam) {
  const k = mulus(p);
  cam.setAttribute('transform', `scale(${(1 + k * 0.06).toFixed(3)}) translate(${(-k * 24).toFixed(1)}, ${(-k * 12).toFixed(1)})`);
}

const awan = el('awanJelagaLatar');
if (awan) awan.setAttribute('transform', `translate(${(-t * 8).toFixed(1)}, 0)`);

const angin = el('anginSaljuHorison');
if (angin) angin.setAttribute('opacity', (0.35 + ombak * 0.15).toFixed(2));

const abu = el('partikelAbuSalju');
if (abu) abu.setAttribute('transform', `translate(${((-t * 28) % 180).toFixed(1)}, ${((t * 20) % 140).toFixed(1)})`);

const keluarga = el('keluargaPurba');
if (keluarga) {
  const pRunduk = mulus(Math.min(1, t / 3.0));
  const tegang = t > 3.0 ? fisika.pegas(t - 3.0, 4.8, 0.75) * 2.5 : 0;
  keluarga.setAttribute('transform', `translate(0, ${(pRunduk * 28 + tegang).toFixed(1)})`);
}

const nAyah = napas;
const nIbu = Math.sin(t * 1.8 - 0.7);

const dadaA = el('dadaNapasAyah');
if (dadaA) dadaA.setAttribute('opacity', (0.5 + nAyah * 0.35).toFixed(2));

const dadaI = el('dadaNapasIbu');
if (dadaI) dadaI.setAttribute('opacity', (0.5 + nIbu * 0.35).toFixed(2));

const uapA = el('embunNapasAyah');
if (uapA) uapA.setAttribute('opacity', Math.max(0, nAyah).toFixed(2));

const uapI = el('embunNapasIbu');
if (uapI) uapI.setAttribute('opacity', Math.max(0, nIbu).toFixed(2));

// skipped: artikulasi mandiri tiap anggota tubuh, tambah saat butuh interaksi tangan/kaki mendetail.

const pKamera = mulus(Math.min(1, t / 7.2));
const pSempit = mulus(Math.max(0, Math.min(1, (t - 3.2) / 3.2)));
const pKunci = Math.max(0, Math.min(1, (t - 3.8) / 0.8));

const dnaUtama = el('subjekRantaiDnaUtama4');
if (dnaUtama) {
  const zoom = 1 + pKamera * 0.22;
  const pilin = Math.sin(t * 1.6) * (1 - pSempit * 0.7) * 5.0;
  dnaUtama.setAttribute('transform', `translate(${(960 * (1 - zoom) - pKamera * 20).toFixed(1)}, ${(540 * (1 - zoom) - pKamera * 35).toFixed(1)}) scale(${zoom.toFixed(3)}) rotate(${pilin.toFixed(2)} 960 540)`);
}

const simpulToba = el('dnaSimpulPenyempitanToba4');
if (simpulToba) {
  const sx = Math.max(0.08, 1 - pSempit * 0.9);
  const sentak = pSempit > 0.85 ? denyut * 0.03 * (1 - mulus(Math.min(1, (t - 6.4) / 1.5))) : 0;
  const skalaX = (sx + sentak).toFixed(3);
  simpulToba.setAttribute('transform', `translate(960, 540) scale(${skalaX}, 1) translate(-960, -540)`);
}

const dnaPurba = el('dnaBagianPurbaAtas4');
if (dnaPurba) {
  const sxPurba = (1 - pSempit * 0.35).toFixed(3);
  dnaPurba.setAttribute('transform', `translate(960, 320) scale(${sxPurba}, 1) translate(-960, -320)`);
}

const dnaModern = el('dnaBagianModernBawah4');
if (dnaModern) {
  const sxModern = (1 - pSempit * 0.65).toFixed(3);
  dnaModern.setAttribute('transform', `translate(960, 760) scale(${sxModern}, 1) translate(-960, -760)`);
}

const retikel = el('retikelBidikSimpul4');
if (retikel) {
  const muncul = mulus(pKunci);
  const pegasSkala = pKunci > 0 ? fisika.pegas(t - 3.8, 4.0, 0.65) : 0;
  const skalaRetikel = Math.max(0.1, 1.35 - muncul * 0.35 + pegasSkala * 0.12 + (pKunci >= 1 ? denyut * 0.025 : 0)).toFixed(3);
  retikel.setAttribute('opacity', (muncul * 0.95).toFixed(2));
  retikel.setAttribute('transform', `translate(960, 540) scale(${skalaRetikel}) translate(-960, -540)`);
}

const panelStatus = el('panelStatusGenom4');
if (panelStatus) {
  const muncul = mulus(Math.min(1, t / 1.6));
  panelStatus.setAttribute('opacity', muncul.toFixed(2));
  panelStatus.setAttribute('transform', `translate(0, ${((1 - muncul) * 18).toFixed(1)})`);
}

const panelKrono = el('panelKronologiToba4');
if (panelKrono) {
  const muncul = mulus(Math.max(0, Math.min(1, (t - 2.2) / 1.6)));
  panelKrono.setAttribute('opacity', muncul.toFixed(2));
  panelKrono.setAttribute('transform', `translate(${((1 - muncul) * -20).toFixed(1)}, 0)`);
}

const labelDna = el('labelPenjelasDna4');
if (labelDna) {
  const muncul = mulus(Math.max(0, Math.min(1, (t - 4.2) / 1.4)));
  labelDna.setAttribute('opacity', muncul.toFixed(2));
}

const cabangPunah = el('cabangPunahArkaik4');
if (cabangPunah) {
  cabangPunah.setAttribute('opacity', Math.max(0.25, 1 - pSempit * 0.55).toFixed(2));
}

const silsilahJauh = el('elemenJauhPohonSilsilah4');
if (silsilahJauh) {
  silsilahJauh.setAttribute('transform', `translate(${(ombak * 3.5).toFixed(1)}, 0)`);
}

const partikel = el('partikelGenetikaMelayang4');
if (partikel) {
  partikel.setAttribute('transform', `translate(${(ombak * 9.0).toFixed(1)}, ${(napas * 11.0).toFixed(1)})`);
}

const cahaya = el('lapisanCahayaDanPartikel4');
if (cahaya) {
  cahaya.setAttribute('opacity', (0.65 + napas * 0.15).toFixed(2));
}

const mikroskopDepan = el('lapisDepanMikroskop4');
if (mikroskopDepan) {
  mikroskopDepan.setAttribute('transform', `translate(${(pKamera * 18 + ombakC * 1.8).toFixed(1)}, ${(pKamera * 10).toFixed(1)})`);
}

const tabungReaksi = el('tabungReaksiMeja4');
if (tabungReaksi) {
  tabungReaksi.setAttribute('transform', `translate(${(pKamera * 8).toFixed(1)}, 0)`);
}
// skipped: per-base-pair individual nucleotide distortion, add when storyboard explicitly mandates atomic macro-zoom.

const peta = el('petaDuniaPurba5');
const sorot = el('sorotPanggung5');
const grafik = el('grafikDinamis5');
const titikKritis = el('titikKritisGrup5');
const badge = el('badgePenyusutan5');
const tagToba = el('tagPeristiwaToba5');
const labelToba = el('labelKalderaToba5');
const debu = el('partikelDebu5');
const nusantara = el('lapisDepanNusantara5');

if (peta) {
  const pMiring = mulus(Math.min(1, Math.max(0, (t - 0.4) / 2.2)));
  const sudutDutch = -pMiring * 2.4;
  peta.setAttribute('transform', `rotate(${sudutDutch.toFixed(2)}, 960, 540)`);
}

if (grafik) {
  const pJatuh = Math.min(1, Math.max(0, (t - 0.6) / 1.8));
  const yJatuh = (pJatuh * pJatuh) * 360;
  let getarKritis = 0;
  if (t > 2.4) {
    const tPasca = t - 2.4;
    getarKritis = Math.sin(tPasca * 26) * Math.exp(-tPasca * 2.2) * 8.5;
  }
  grafik.setAttribute('transform', `translate(0, ${(yJatuh + getarKritis).toFixed(2)})`);
}

if (titikKritis) {
  let getarLantai = 0;
  if (t > 2.4 && t < 3.8) {
    const tLantai = t - 2.4;
    getarLantai = Math.sin(tLantai * 32) * Math.exp(-tLantai * 3) * 5;
  }
  titikKritis.setAttribute('transform', `translate(0, ${getarLantai.toFixed(2)})`);
  if (t >= 2.4) {
    titikKritis.setAttribute('opacity', (0.85 + denyut * 0.15).toFixed(2));
  }
}

if (badge) {
  const pBadge = mulus(Math.min(1, Math.max(0, (t - 2.5) / 0.6)));
  const yBadge = (1 - pBadge) * 18;
  badge.setAttribute('opacity', pBadge.toFixed(2));
  badge.setAttribute('transform', `translate(0, ${yBadge.toFixed(2)})`);
}

if (tagToba) {
  const pTag = mulus(Math.min(1, Math.max(0, (t - 3.7) / 0.9)));
  tagToba.setAttribute('opacity', pTag.toFixed(2));
  tagToba.setAttribute('transform', `translate(0, ${((1 - pTag) * 14).toFixed(2)})`);
}

if (labelToba) {
  const pLabel = mulus(Math.min(1, Math.max(0, (t - 4.2) / 0.8)));
  labelToba.setAttribute('opacity', pLabel.toFixed(2));
}

if (debu) {
  const driftY = (t * -16) % 150;
  const driftX = ombak * 10;
  debu.setAttribute('transform', `translate(${driftX.toFixed(2)}, ${driftY.toFixed(2)})`);
  debu.setAttribute('opacity', (0.35 + napas * 0.15).toFixed(2));
}

if (sorot) {
  sorot.setAttribute('opacity', (0.75 + napas * 0.1).toFixed(2));
}

if (nusantara) {
  nusantara.setAttribute('transform', `translate(0, ${(ombak * 2.5).toFixed(2)})`);
}

// skipped: [morphing kurva SVG path], add when [titik d-path eksak disediakan].

const langit = el('latarLangitDanBukit');
if (langit) {
  const camPush = 1 + mulus(p) * 0.04;
  langit.setAttribute('transform', `scale(${camPush.toFixed(3)})`);
}

const rantingBg = el('siluetPohonCakrawala');
if (rantingBg) {
  rantingBg.setAttribute('transform', `rotate(${(ombak * 0.7).toFixed(2)} 640 280)`);
}

const rantingFg = el('siluetRantingKananBawah');
if (rantingFg) {
  rantingFg.setAttribute('transform', `rotate(${(ombakC * 1.5).toFixed(2)} 1100 680)`);
}

const batangGantung = el('patahanBatangMenggantung');
if (batangGantung) {
  const ayunBatang = Math.sin(t * 1.6) * 3.2;
  batangGantung.setAttribute('transform', `rotate(${ayunBatang.toFixed(2)} 320 250)`);
}

const palem = el('pohonPalemKering');
if (palem) {
  const guncangPalem = t < 3.0 ? (1 - t / 3.0) * getar * 0.5 : 0;
  palem.setAttribute('transform', `rotate(${(guncangPalem + napas * 0.4).toFixed(2)} 260 550)`);
}

const hujanAbu = el('hujanAbuSilikaPartikel');
if (hujanAbu) {
  const yJatuh = (t * 140) % 240;
  const xHanyut = Math.sin(t * 2.0) * 12;
  const opasitasAbu = t > 5.5 ? Math.max(0.25, 1 - (t - 5.5) / 2.5) : 0.85;
  hujanAbu.setAttribute('transform', `translate(${xHanyut.toFixed(1)}, ${yJatuh.toFixed(1)})`);
  hujanAbu.setAttribute('opacity', opasitasAbu.toFixed(2));
}

const abu = el('lapisanAbuToba');
if (abu) {
  const tTumpuk = Math.min(1, Math.max(0, (t - 0.4) / 3.4));
  const kurvaTurun = mulus(tTumpuk);
  const tSettle = Math.max(0, t - 3.8);
  const pantul = tSettle > 0 && tSettle < 1.6 ? (1 - fisika.pegas(tSettle, 4.5, 0.65)) * 5 : 0;
  const yTurun = ((1 - kurvaTurun) * -75 + pantul).toFixed(1);
  const tebalSkala = Math.max(0.05, kurvaTurun).toFixed(3);
  abu.setAttribute('transform', `translate(0, ${yTurun}) scale(1, ${tebalSkala})`);
  abu.setAttribute('opacity', Math.min(1, kurvaTurun * 1.5).toFixed(2));
}

const semak = el('semakMatiTertimbun');
if (semak) {
  const tTindih = mulus(Math.min(1, Math.max(0, (t - 0.8) / 3.0)));
  const turunSemak = (tTindih * 10).toFixed(1);
  const penyek = (1 - tTindih * 0.25).toFixed(3);
  semak.setAttribute('transform', `translate(0, ${turunSemak}) scale(1, ${penyek})`);
  semak.setAttribute('opacity', (1 - tTindih * 0.45).toFixed(2));
}

const labelGeo = el('labelLapisanGeologi');
if (labelGeo) {
  const munculGeo = mulus(Math.min(1, Math.max(0, (t - 0.6) / 1.0)));
  labelGeo.setAttribute('opacity', munculGeo.toFixed(2));
}

const indikator = el('indikatorKetebalan15cm');
if (indikator) {
  const tumbuhGaris = mulus(Math.min(1, Math.max(0, (t - 4.0) / 0.8)));
  indikator.setAttribute('transform', `scale(1, ${tumbuhGaris.toFixed(3)})`);
  indikator.setAttribute('opacity', tumbuhGaris.toFixed(2));
}

const badge = el('badgeLabel15cm');
if (badge) {
  const tBadge = Math.max(0, t - 4.4);
  const popBadge = tBadge > 0 ? Math.min(1, fisika.pegas(tBadge, 3.8, 0.65)) : 0;
  badge.setAttribute('transform', `scale(${popBadge.toFixed(3)})`);
  badge.setAttribute('opacity', Math.min(1, tBadge * 4).toFixed(2));
}
// skipped: fisika partikel individual per butir silika, tambahkan bila migrasi ke canvas/WebGL.

const veilProgress = mulus(Math.min(1, t / 2.5));
const rayInProg = mulus(Math.min(1, Math.max(0, (t - 1.2) / 1.6)));
const rayReflectProg = mulus(Math.min(1, Math.max(0, (t - 2.6) / 1.8)));
const impactTime = Math.max(0, 1 - Math.abs(t - 2.7) * 4);
const tempDropProg = mulus(Math.min(1, Math.max(0, (t - 4.0) / 2.6)));

const bintang = el('medanBintang7');
if (bintang) {
  bintang.setAttribute('transform', `translate(${(-t * 2).toFixed(1)}, ${(ombak * 0.8).toFixed(1)})`);
}

const satelit = el('satelitBumiPurba7');
if (satelit) {
  satelit.setAttribute('transform', `translate(${(t * 4).toFixed(1)}, ${(ombakC * 2.5).toFixed(1)})`);
}

const bumi = el('kelengkunganBumi7');
if (bumi) {
  bumi.setAttribute('transform', `translate(0, ${(napas * 1.5).toFixed(1)})`);
}

const aerosol = el('lapisanAerosolBelerang7');
if (aerosol) {
  aerosol.setAttribute('opacity', (0.15 + veilProgress * 0.85).toFixed(2));
  aerosol.setAttribute('transform', `translate(${(ombak * 2.5).toFixed(1)}, ${(napas * 1.8).toFixed(1)})`);
}

const molekul = el('molekulAerosol7');
if (molekul) {
  molekul.setAttribute('transform', `translate(${(ombakC * 3.5).toFixed(1)}, ${(ombak * 2.5).toFixed(1)})`);
}

const radiasi = el('dinamikaRadiasiSurya7');
if (radiasi) {
  radiasi.setAttribute('opacity', (0.9 + napas * 0.1).toFixed(2));
}

const sinarDatang = el('berkasSinarDatang7');
if (sinarDatang) {
  const dx = (1 - rayInProg) * 350;
