const tSentak = 1.5;
const cam = mulus(t / dur);

if (pemburu) {
  let hx = 0;
  let hy = napas * 1.6;
  if (t < tSentak) {
    const ancang = mulus(t / tSentak);
    hx = -ancang * 5;
    hy += ancang * 7;
  } else {
    const pulih = mulus(Math.min(1, (t - tSentak) / 1.2));
    const pegasSentak = fisika.pegas(t - tSentak, 4.2, 0.62) * 14;
    hx = -5 * (1 - pulih) + pegasSentak * 0.25;
    hy += 7 * (1 - pulih) - pegasSentak;
  }
  pemburu.setAttribute('transform', `translate(${hx.toFixed(2)}, ${hy.toFixed(2)})`);
}

if (kerang) {
  if (t < tSentak) {
    kerang.setAttribute('transform', 'translate(0, 0)');
    kerang.setAttribute('opacity', '1');
  } else if (t < 2.8) {
    const pLayang = mulus((t - tSentak) / 1.3);
    const kx = -pLayang * 95;
    const ky = -Math.sin(pLayang * Math.PI) * 75 + pLayang * 35;
    const rot = (pLayang * 260).toFixed(1);
    const op = pLayang > 0.85 ? Math.max(0, (1 - pLayang) / 0.15).toFixed(2) : '1';
    kerang.setAttribute('transform', `translate(${kx.toFixed(1)}, ${ky.toFixed(1)}) rotate(${rot})`);
    kerang.setAttribute('opacity', op);
  } else {
    kerang.setAttribute('opacity', '0');
  }
}

if (cipratan) {
  if (t >= tSentak && t < 2.1) {
    const pCip = (t - tSentak) / 0.6;
    const op = (1 - mulus(pCip)).toFixed(2);
    const yDrop = (-pCip * 18).toFixed(1);
    cipratan.setAttribute('opacity', op);
    cipratan.setAttribute('transform', `translate(0, ${yDrop}) scale(${(0.8 + pCip * 0.6).toFixed(2)})`);
  } else {
    cipratan.setAttribute('opacity', '0');
  }
}

